<template><div class="page-wrap"><div class="page-heading"><span class="eyebrow">GUIDES & TIPS</span><h1>攻略与指南</h1><p>让每一次开始都更顺利。</p></div><div class="guide-grid"><RouterLink v-for="g in guides" :key="g.id" :to="`/guides/${g.slug}`" class="guide-card"><span class="guide-card-icon">✎</span><small>{{ g.category }} · {{ g.readTime }}</small><h2>{{ g.title }}</h2><p>{{ g.summary }}</p><div class="guide-card-foot"><span>{{ g.author }}</span><b>阅读文章 →</b></div></RouterLink></div></div></template><script setup>import{inject,computed}from'vue';const data=inject('siteData'),guides=computed(()=>data.guides.filter(g=>g.published))</script>
